{"file_text": "@namespace sv_6f12f880dd00449993c3eb9a029b2cda.Components.Pages.Settings
@using sv_6f12f880dd00449993c3eb9a029b2cda.Models

<div class="settings-section">
    <h4>Security</h4>

    <ChangePasswordPanel OnChangePassword="OnChangePassword" />

    <div class="card mb-3">
        <div class="card-body d-flex justify-content-between align-items-center">
            <div>
                <strong>Two-Factor Authentication</strong>
                <div class="text-muted small">
                    @if (Security?.TwoFactorEnabled == true)
                    {
                        <span class="badge bg-success me-1">Enabled</span>
                    }
                    else
                    {
                        <span class="badge bg-secondary me-1">Disabled</span>
                    }
                </div>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox"
                       checked="@(Security?.TwoFactorEnabled ?? false)"
                       @onchange="Toggle2FA" />
            </div>
        </div>
    </div>

    @if (Security?.LastPasswordChange is not null)
    {
        <p class="text-muted small">
            Last password change: @Security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
        </p>
    }

    <h5>Active Sessions</h5>
    <div class="table-responsive">
        <table class="table table-striped">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @if (Security?.Sessions is not null)
                {
                    @foreach (var session in Security.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session.Id != CurrentSessionId)
                                {
                                    <button class="btn btn-sm btn-outline-danger"
                                            @onclick="() => RequestRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="badge bg-info">Current</span>
                                }
                            </td>
                        </tr>
                    }
                }
            </tbody>
        </table>
    </div>

    <RevokeSessionDialog Session="_sessionToRevoke"
                         OnConfirm="ConfirmRevoke"
                         OnCancel="CancelRevoke" />
</div>

@code {
    [Parameter] public SecuritySettings? Security { get; set; }
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }
    [Parameter] public EventCallback<bool> OnToggle2FA { get; set; }

    // First session is treated as "current"
    private string CurrentSessionId => Security?.Sessions.FirstOrDefault()?.Id ?? "";

    private ActiveSession? _sessionToRevoke;

    private void RequestRevoke(ActiveSession session) => _sessionToRevoke = session;
    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
    }

    private async Task Toggle2FA(ChangeEventArgs e)
    {
        var enabled = (bool)e.Value!;
        await OnToggle2FA.InvokeAsync(enabled);
    }
}
