{"file_text": "@namespace sv_6f12f880dd00449993c3eb9a029b2cda.Components.Pages.Settings
@using sv_6f12f880dd00449993c3eb9a029b2cda.Models

<div class="settings-section">
    <h4>Appearance</h4>

    <div class="mb-4">
        <label class="form-label fw-bold">Theme</label>
        <div>
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <div class="form-check form-check-inline">
                    <input class="form-check-input" type="radio" name="theme"
                           id="@($"theme-{theme}")" value="@theme"
                           checked="@(Theme == theme)"
                           @onchange="() => Theme = theme" />
                    <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                </div>
            }
        </div>
    </div>

    <div class="mb-4">
        <label class="form-label fw-bold">Font Size</label>
        <div>
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <div class="form-check form-check-inline">
                    <input class="form-check-input" type="radio" name="fontSize"
                           id="@($"fs-{size}")" value="@size"
                           checked="@(FontSize == size)"
                           @onchange="() => FontSize = size" />
                    <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                </div>
            }
        </div>
    </div>

    <div class="mb-4">
        <label class="form-label fw-bold">Language</label>
        <select class="form-select" style="max-width: 300px;"
                @bind="Language">
            <option value="English">English</option>
            <option value="Spanish">Spanish</option>
            <option value="French">French</option>
            <option value="German">German</option>
            <option value="Japanese">Japanese</option>
            <option value="Chinese">Chinese</option>
        </select>
    </div>

    <div class="mb-4">
        <div class="form-check form-switch">
            <input class="form-check-input" type="checkbox" id="compactMode"
                   checked="@CompactMode"
                   @onchange="e => CompactMode = (bool)e.Value!" />
            <label class="form-check-label" for="compactMode">Compact Mode</label>
        </div>
    </div>

    <h5>Live Preview</h5>
    <div class="appearance-preview p-3 rounded border mb-4"
         style="@PreviewStyle">
        <h6 style="margin: 0 0 8px;">Preview Area</h6>
        <p style="margin: 0 0 6px;">This is how your content will look with the selected settings.</p>
        <button class="btn btn-sm @(Theme == "Dark" ? "btn-light" : "btn-dark")">Sample Button</button>
        <span class="ms-2 badge @(Theme == "Dark" ? "bg-light text-dark" : "bg-dark")">Badge</span>
    </div>

    <button class="btn btn-primary" @onclick="Save" disabled="@IsSaving">
        @if (IsSaving) { <span class="spinner-border spinner-border-sm me-1"></span> }
        Save
    </button>

    @if (ShowSuccess)
    {
        <div class="alert alert-success mt-3 fade show">Appearance settings saved!</div>
    }
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string Theme = "Light";
    private string FontSize = "Medium";
    private string Language = "English";
    private bool CompactMode;
    private bool IsSaving;
    private bool ShowSuccess;
    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_initialized)
        {
            Theme = Settings.Theme;
            FontSize = Settings.FontSize;
            Language = Settings.Language;
            CompactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private string PreviewStyle
    {
        get
        {
            var bg = Theme == "Dark" ? "#1e1e1e" : Theme == "System" ? "#f0f0f0" : "#ffffff";
            var fg = Theme == "Dark" ? "#e0e0e0" : "#212529";
            var fs = FontSize switch { "Small" => "13px", "Large" => "18px", _ => "15px" };
            var pad = CompactMode ? "8px" : "16px";
            return $"background-color:{bg}; color:{fg}; font-size:{fs}; padding:{pad};";
        }
    }

    private async Task Save()
    {
        IsSaving = true;
        var updated = new AppearanceSettings(Theme, FontSize, Language, CompactMode);
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        ShowSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        ShowSuccess = false;
        StateHasChanged();
    }
}
