.settings-layout {
    display: flex;
    gap: 2rem;
    min-height: 70vh;
}

::deep .settings-sidebar {
    min-width: 200px;
    max-width: 220px;
    border-right: 1px solid #dee2e6;
    padding-right: 1rem;
}

::deep .sidebar-title {
    padding: 0.5rem 1rem;
    margin-bottom: 0.5rem;
    color: #6c757d;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

::deep .settings-sidebar .nav-link {
    color: #495057;
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    padding: 0.6rem 1rem;
    border-radius: 0.375rem;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-size: 0.95rem;
}

::deep .settings-sidebar .nav-link:hover {
    background-color: #f8f9fa;
}

::deep .settings-sidebar .nav-link.active {
    background-color: #0d6efd;
    color: #fff;
}

.settings-content {
    flex: 1;
    min-width: 0;
}

::deep .settings-section {
    max-width: 700px;
}

::deep .avatar-preview {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
}

::deep .avatar-preview img {
    border: 3px solid #dee2e6;
    object-fit: cover;
}

::deep .appearance-preview {
    transition: all 0.2s ease;
}

